+
+assertEq(test2({x: 1, y: 2}, (o) => delete o.y), 1);
+assertEq(test2([1,2], (o) => delete o[1]), 1);
+assertEq(test2([1,2], (o) => {o.length = 0}), 1);
+
+assertEq(test2({x: 1, y: 2, z: 3}, (o) => delete o.y), 4);
